begin;
create extension if not exists pgcrypto;
create type public.user_role as enum ('admin','viewer');
create type public.processing_status as enum ('pending','extracting','analyzing','reconciling','completed','failed');
create type public.billing_status as enum ('draft','processing','review','approved','invoiced','closed');
create type public.reconciliation_status as enum ('MATCH','PDF_ONLY','CSV_ONLY','QUANTITY_MISMATCH','COMPONENT_MISMATCH','DATE_MISMATCH','DUPLICATE','RETURNED','REVIEW_REQUIRED');

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,full_name text,role public.user_role not null default 'viewer',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.billing_periods(id uuid primary key default gen_random_uuid(),name text not null,start_date date not null,end_date date not null,customer text not null,status public.billing_status not null default 'draft',created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint valid_period check(end_date>=start_date));
create table public.documents(id uuid primary key default gen_random_uuid(),original_filename text not null,mime_type text not null,document_type text not null,storage_path text not null unique,encrypted boolean not null default true,encryption_version text not null,encrypted_file_key text not null,iv text not null,auth_tag text not null,key_iv text not null,key_auth_tag text not null,sha256 text not null,size_bytes bigint not null check(size_bytes>0),status public.processing_status not null default 'pending',uploaded_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(sha256,document_type));
create table public.document_pages(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,page_number int not null check(page_number>0),page_type text not null,markdown text,text_sufficient boolean not null default false,needs_ocr boolean not null default false,confidence numeric(5,4),created_at timestamptz not null default now(),unique(document_id,page_number));
create table public.csv_imports(id uuid primary key default gen_random_uuid(),document_id uuid not null unique references public.documents(id) on delete cascade,encoding text not null,delimiter text not null default ';',record_count int not null default 0,created_at timestamptz not null default now());
create table public.component_catalog(code text primary key,description text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.csv_records(id uuid primary key default gen_random_uuid(),csv_import_id uuid not null references public.csv_imports(id) on delete cascade,delivery_note_number text not null,component_code text not null references public.component_catalog(code),component_name text,dispatch_date date,dispatch_time time,unit_number text not null,blood_group text,expiration_date date,returned boolean not null default false,raw jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(csv_import_id,delivery_note_number,component_code,unit_number));
create table public.delivery_notes(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,delivery_note_number text not null,dispatch_date date,dispatch_time time,destination text,total_products int,page_number int,confidence numeric(5,4) not null default 0,extraction_original jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(document_id,delivery_note_number,page_number));
create table public.delivery_note_items(id uuid primary key default gen_random_uuid(),delivery_note_id uuid not null references public.delivery_notes(id) on delete cascade,component_code text references public.component_catalog(code),product text,unit_number text not null,blood_group text,expiration_date date,volume text,observations text,confidence numeric(5,4) not null default 0,original_value jsonb not null default '{}'::jsonb,corrected_value jsonb,corrected_by uuid references public.profiles(id),corrected_at timestamptz,created_at timestamptz not null default now(),unique(delivery_note_id,component_code,unit_number));
create table public.reconciliations(id uuid primary key default gen_random_uuid(),billing_period_id uuid not null references public.billing_periods(id) on delete cascade,pdf_document_id uuid references public.documents(id),csv_document_id uuid references public.documents(id),status public.processing_status not null default 'pending',created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.reconciliation_items(id uuid primary key default gen_random_uuid(),reconciliation_id uuid not null references public.reconciliations(id) on delete cascade,delivery_note_number text not null,component_code text,unit_number text not null,status public.reconciliation_status not null,csv_record_id uuid references public.csv_records(id),pdf_item_id uuid references public.delivery_note_items(id),notes jsonb not null default '[]'::jsonb,manual_decision jsonb,reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create table public.component_prices(id uuid primary key default gen_random_uuid(),component_code text not null references public.component_catalog(code),description text,unit_price numeric(18,2),effective_from date not null,effective_to date,active boolean not null default true,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint price_nonnegative check(unit_price is null or unit_price>=0),constraint price_dates check(effective_to is null or effective_to>=effective_from));
create table public.ai_runs(id uuid primary key default gen_random_uuid(),document_id uuid references public.documents(id) on delete set null,task text not null,model text not null,input_chars int,toon_chars int,estimated_input_tokens int,output_tokens int,latency_ms int,status text not null,error text,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete set null,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}'::jsonb,ip_address inet,created_at timestamptz not null default now());

create index idx_csv_delivery on public.csv_records(delivery_note_number);
create index idx_csv_component on public.csv_records(component_code);
create index idx_csv_unit on public.csv_records(unit_number);
create index idx_csv_dispatch on public.csv_records(dispatch_date);
create index idx_dn_number on public.delivery_notes(delivery_note_number);
create index idx_dn_doc on public.delivery_notes(document_id);
create index idx_dni_component on public.delivery_note_items(component_code);
create index idx_dni_unit on public.delivery_note_items(unit_number);
create index idx_rec_period on public.reconciliations(billing_period_id);
create index idx_rec_items_note on public.reconciliation_items(delivery_note_number);
create index idx_audit_created on public.audit_logs(created_at desc);

create or replace function public.set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now(); return new; end$$;
do $$ declare t text; begin foreach t in array array['profiles','billing_periods','reconciliations','component_catalog','component_prices'] loop execute format('create trigger trg_%s_updated before update on public.%I for each row execute function public.set_updated_at()',t,t); end loop; end $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles p where p.id=auth.uid() and p.active and p.role='admin')$$;
create or replace function public.is_active_user() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles p where p.id=auth.uid() and p.active)$$;

alter table public.profiles enable row level security;
alter table public.billing_periods enable row level security;
alter table public.documents enable row level security;
alter table public.document_pages enable row level security;
alter table public.csv_imports enable row level security;
alter table public.csv_records enable row level security;
alter table public.delivery_notes enable row level security;
alter table public.delivery_note_items enable row level security;
alter table public.reconciliations enable row level security;
alter table public.reconciliation_items enable row level security;
alter table public.component_catalog enable row level security;
alter table public.component_prices enable row level security;
alter table public.ai_runs enable row level security;
alter table public.audit_logs enable row level security;

create policy profiles_self_read on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy profiles_admin_write on public.profiles for all using(public.is_admin()) with check(public.is_admin());
create policy periods_read on public.billing_periods for select using(public.is_active_user());
create policy periods_admin_write on public.billing_periods for all using(public.is_admin()) with check(public.is_admin());
create policy documents_read on public.documents for select using(public.is_active_user());
create policy documents_admin_write on public.documents for all using(public.is_admin()) with check(public.is_admin());
create policy pages_read on public.document_pages for select using(public.is_active_user());
create policy pages_admin_write on public.document_pages for all using(public.is_admin()) with check(public.is_admin());
create policy csv_imports_read on public.csv_imports for select using(public.is_active_user());
create policy csv_imports_admin_write on public.csv_imports for all using(public.is_admin()) with check(public.is_admin());
create policy csv_records_read on public.csv_records for select using(public.is_active_user());
create policy csv_records_admin_write on public.csv_records for all using(public.is_admin()) with check(public.is_admin());
create policy notes_read on public.delivery_notes for select using(public.is_active_user());
create policy notes_admin_write on public.delivery_notes for all using(public.is_admin()) with check(public.is_admin());
create policy note_items_read on public.delivery_note_items for select using(public.is_active_user());
create policy note_items_admin_write on public.delivery_note_items for all using(public.is_admin()) with check(public.is_admin());
create policy rec_read on public.reconciliations for select using(public.is_active_user());
create policy rec_admin_write on public.reconciliations for all using(public.is_admin()) with check(public.is_admin());
create policy rec_items_read on public.reconciliation_items for select using(public.is_active_user());
create policy rec_items_admin_write on public.reconciliation_items for all using(public.is_admin()) with check(public.is_admin());
create policy catalog_read on public.component_catalog for select using(public.is_active_user());
create policy catalog_admin_write on public.component_catalog for all using(public.is_admin()) with check(public.is_admin());
create policy prices_read on public.component_prices for select using(public.is_active_user());
create policy prices_admin_write on public.component_prices for all using(public.is_admin()) with check(public.is_admin());
create policy ai_admin_only on public.ai_runs for all using(public.is_admin()) with check(public.is_admin());
create policy audit_admin_only on public.audit_logs for select using(public.is_admin());
create policy audit_insert_server on public.audit_logs for insert with check(auth.uid()=user_id or public.is_admin());

insert into storage.buckets(id,name,public) values('documents-encrypted','documents-encrypted',false),('generated-reports','generated-reports',false) on conflict(id) do update set public=false;
create policy encrypted_admin_select on storage.objects for select using(bucket_id='documents-encrypted' and public.is_admin());
create policy encrypted_admin_insert on storage.objects for insert with check(bucket_id='documents-encrypted' and public.is_admin() and (storage.foldername(name))[1]=auth.uid()::text);
create policy encrypted_admin_delete on storage.objects for delete using(bucket_id='documents-encrypted' and public.is_admin());
create policy reports_active_select on storage.objects for select using(bucket_id='generated-reports' and public.is_active_user());
create policy reports_admin_write on storage.objects for all using(bucket_id='generated-reports' and public.is_admin()) with check(bucket_id='generated-reports' and public.is_admin());
commit;
